import { StepData } from './Step/StepTypes';

export interface StepperProps extends React.HTMLProps<HTMLDivElement> {
  /**
   * Identifying value for the button.
   */
  id: string;
   /**
   * Array of all step labels to be displayed.
   */
  steps: StepData[];
  /**
   * Array of error step to be displayed.
   */
  errorSteps?: [];
    /**
   * Index of the active step withing the steps array.
   */
  activeStep?: number;  
    /**
   * Determines the color palette of the step buttons.
   */
  colour?: "primary" | "secondary" | "tertiary";
}
